use gungraun::{library_benchmark, library_benchmark_group, main};
use std::hint::black_box; fn decode_line(line: String) -> (u8, u8, u8) { if let &[a, b, c] = line.split(";") .map(|s| s.parse::<u8>().unwrap()) .collect::<Vec<u8>>() .as_slice() { (a, b, c) } else { panic!("Wrong input format in line '{line}'"); }
} #[library_benchmark]
#[benches::from_file(file = "benches/inputs", setup = decode_line)]
fn some_bench((a, b, c): (u8, u8, u8)) -> (u16, u8, u8) { black_box(my_lib::rgb_to_hsv(black_box(a), black_box(b), black_box(c)))
} library_benchmark_group!(name = my_group; benchmarks = some_bench);
