)]
#[bench::two_threads(2)]
fn bench_threads(num_threads: usize) -> Vec<u64> { black_box(my_lib::find_primes_multi_thread(num_threads))
}
# library_benchmark_group!(name = my_group; benchmarks = bench_threads);
# fn main() {
# main!(library_benchmark_groups = my_group);
# } Setting the EntryPoint::None disables the default toggle but also --collect-atstart=no, which is why we have to set the option manually. Altogether, running the benchmark will show: lib_bench_threads::my_group::bench_threads two_threads:2 ## pid: 2251257 thread: 1 part: 1 |N/A Command: target/release/deps/lib_bench_threads-b85159a94ccb3851 Instructions: 0|N/A (*********) L1 Hits: 0|N/A (*********) LL Hits: 0|N/A (*********) RAM Hits: 0|N/A (*********) Total read+write: 0|N/A (*********) Estimated Cycles: 0|N/A (*********) ## pid: 2251257 thread: 2 part: 1 |N/A Command: target/release/deps/lib_bench_threads-b85159a94ccb3851 Instructions: 2460501|N/A (*********) L1 Hits: 2534935|N/A (*********) LL Hits: 11|N/A (*********) RAM Hits: 187|N/A (*********) Total read+write: 2535133|N/A (*********) Estimated Cycles: 2541535|N/A (*********) ## pid: 2251257 thread: 3 part: 1 |N/A Command: target/release/deps/lib_bench_threads-b85159a94ccb3851 Instructions: 3650408|N/A (*********) L1 Hits: 3724282|N/A (*********) LL Hits: 4|N/A (*********) RAM Hits: 131|N/A (*********) Total read+write: 3724417|N/A (*********) Estimated Cycles: 3728887|N/A (*********) ## Total Instructions: 6110909|N/A (*********) L1 Hits: 6259217|N/A (*********) LL Hits: 15|N/A (*********) RAM Hits: 318|N/A (*********) Total read+write: 6259550|N/A (*********) Estimated Cycles: 6270422|N/A (*********) Gungraun result: Ok. 1 without regressions; 0 regressed; 0 filtered; 1 benchmarks finished in 0.49333s

