Since we can put any code building the Command in the function itself, the setup and teardown of #[binary_benchmark], #[bench] and #[benches] work differently. # extern crate gungraun;
# macro_rules! env { ($m:tt) => {{ "/some/path" }} }
use gungraun::{binary_benchmark, binary_benchmark_group, main}; fn create_file() { std::fs::write("foo.txt", "some content").unwrap();
} #[binary_benchmark]
#[bench::foo(args = ("foo.txt"), setup = create_file())]
fn bench_binary(path: &str) -> gungraun::Command { gungraun::Command::new(env!("CARGO_BIN_EXE_my-foo")) .arg(path) .build()
} binary_benchmark_group!(name = my_group; benchmarks = bench_binary);
# fn main() {
main!(binary_benchmark_groups = my_group);
# } setup, which is here the expression create_file(), is not evaluated right away and the return value of setup is not used as input for the function! Instead, the expression in setup is getting evaluated and executed just before the benchmarked Command is executed . Similarly, teardown is executed after the Command is executed . In the example above, setup creates always the same file and is pretty static. It's possible to use the same arguments for setup (teardown) and the function using the path (or file pointer) to a function as you're used to from library benchmarks: # extern crate gungraun;
# macro_rules! env { ($m:tt) => {{ "/some/path" }} }
use gungraun::{binary_benchmark, binary_benchmark_group, main}; fn create_file(path: &str) { std::fs::write(path, "some content").unwrap();
} fn delete_file(path: &str) { std::fs::remove_file(path).unwrap();
} #[binary_benchmark]
// Note the missing parentheses for `setup` of the function `create_file` which
// tells Gungraun to pass the `args` to the `setup` function AND the
// function `bench_binary`
#[bench::foo(args = ("foo.txt"), setup = create_file)]
// Same for `teardown`
#[bench::bar(args = ("bar.txt"), setup = create_file, teardown = delete_file)]
fn bench_binary(path: &str) -> gungraun::Command { gungraun::Command::new(env!("CARGO_BIN_EXE_my-foo")) .arg(path) .build()
} binary_benchmark_group!(name = my_group; benchmarks = bench_binary);
# fn main() {
main!(binary_benchmark_groups = my_group);
# }

