It is recommended to start with the high-level api using the #[binary_benchmark] attribute, since you can fall back to the low-level api in a few steps with the binary_benchmark_attribute! macro as shown below. The other way around is much more involved. # extern crate gungraun;
# macro_rules! env { ($m:tt) => {{ "/some/path" }} }
use gungraun::{ binary_benchmark, binary_benchmark_attribute, binary_benchmark_group, main, BinaryBenchmark, Bench
}; #[binary_benchmark]
#[bench::some_id("foo")]
fn attribute_benchmark(arg: &str) -> gungraun::Command { gungraun::Command::new(env!("CARGO_BIN_EXE_my-binary")) .arg(arg) .build()
} binary_benchmark_group!( name = low_level; benchmarks = |group: &mut BinaryBenchmarkGroup| { group .binary_benchmark(binary_benchmark_attribute!(attribute_benchmark)) .binary_benchmark( BinaryBenchmark::new("low_level_benchmark") .bench( Bench::new("some_id").command( gungraun::Command::new(env!("CARGO_BIN_EXE_my-binary")) .arg("bar") .build() ) ) ) }
); # fn main() {
main!(binary_benchmark_groups = low_level);
# } As shown above, there's no need to transcribe the function attribute_benchmark with the #[binary_benchmark] attribute into the low-level api structures. Just keep it as it is and add it to a the group with group.binary_benchmark(binary_benchmark_attribute(attribute_benchmark)). That's it! You can continue hacking on your benchmarks in the low-level api.

