Based on that data, we could define for example hard limits (or soft limits or both whatever you think is appropriate) to ensure bubble_sort is not getting worse than that. # extern crate gungraun;
# mod my_lib { pub fn bubble_sort(_: Vec<i32>) -> Vec<i32> { vec![] } }
use gungraun::{ library_benchmark, library_benchmark_group, main, LibraryBenchmarkConfig, Dhat, DhatMetric
};
use std::hint::black_box; #[library_benchmark]
#[bench::worst_case_3( args = (vec![3, 2, 1]), config = LibraryBenchmarkConfig::default() .tool(Dhat::default() .hard_limits([ (DhatMetric::ReadsBytes, 24), (DhatMetric::WritesBytes, 32) ]) )
)]
fn bench_bubble_sort(array: Vec<i32>) -> Vec<i32> { black_box(my_lib::bubble_sort(array))
} library_benchmark_group!(name = my_group; benchmarks = bench_bubble_sort); # fn main() {
main!( config = LibraryBenchmarkConfig::default() .tool(Dhat::default()); library_benchmark_groups = my_group
);
# } Now, if bubble_sort would read more than 24 bytes or if there were more than 32 bytes of writes during the benchmark, the benchmark would fail and exit with error.

