use std::hint::black_box;
use gungraun::{ library_benchmark, library_benchmark_group, main, LibraryBenchmarkConfig, ValgrindTool,
}; #[library_benchmark( config = LibraryBenchmarkConfig::default() .default_tool(ValgrindTool::DHAT)
)]
fn bench_library() -> Vec<u64> { black_box(benchmark_tests::find_primes_multi_thread(black_box(1)))
} library_benchmark_group!(name = my_group; benchmarks = bench_library);
