In library benchmarks you might need to use EntryPoint::None in order to make the client requests work as expected: # extern crate gungraun;
use gungraun::{main, library_benchmark_group, library_benchmark};
use std::hint::black_box; pub mod my_lib { #[inline(never)] fn bubble_sort(input: Vec<i32>) -> Vec<i32> { // The algorithm
# input } pub fn pre_bubble_sort(input: Vec<i32>) -> Vec<i32> { println!("Doing something before the function call"); gungraun::client_requests::callgrind::start_instrumentation(); let result = bubble_sort(input); gungraun::client_requests::callgrind::stop_instrumentation(); result }
} #[library_benchmark]
#[bench::small(vec![3, 2, 1])]
#[bench::bigger(vec![5, 4, 3, 2, 1])]
fn bench_function(array: Vec<i32>) -> Vec<i32> { black_box(my_lib::pre_bubble_sort(array))
} library_benchmark_group!(name = my_group; benchmarks = bench_function);
# fn main() {
main!(library_benchmark_groups = my_group);
# } The default EntryPoint sets the --toggle-collect to the benchmark function (here bench_function) and --collect-atstart=no. So, Callgrind starts collecting the events when entering the benchmark function, not the moment start_instrumentation is called. This behaviour can be remedied with EntryPoint::None: # extern crate gungraun;
use gungraun::{ main, library_benchmark_group, library_benchmark, LibraryBenchmarkConfig, client_requests, EntryPoint, Callgrind
};
use std::hint::black_box; pub mod my_lib { #[inline(never)] fn bubble_sort(input: Vec<i32>) -> Vec<i32> { // The algorithm
# input } pub fn pre_bubble_sort(input: Vec<i32>) -> Vec<i32> { println!("Doing something before the function call"); gungraun::client_requests::callgrind::start_instrumentation(); let result = bubble_sort(input); gungraun::client_requests::callgrind::stop_instrumentation(); result }
} #[library_benchmark( config = LibraryBenchmarkConfig::default() .tool(Callgrind::with_args(["--collect-atstart=no"]) .entry_point(EntryPoint::None) )
)]
#[bench::small(vec![3, 2, 1])]
#[bench::bigger(vec![5, 4, 3, 2, 1])]
fn bench_function(array: Vec<i32>) -> Vec<i32> { black_box(my_lib::pre_bubble_sort(array))
} library_benchmark_group!(name = my_group; benchmarks = bench_function);
# fn main() {
main!(library_benchmark_groups = my_group);
# } As the standard toggle is now switched off and the option --collect-atstart=no is also omitted, you must specify --collect-atstart=no manually in LibraryBenchmarkConfig::raw_callgrind_args. Please see the docs for more details!

